const input = $input.first().json;
// Recover ticket fields from a normal webhook body or legacy nested webhook bodies.
const allowed = ['ticketId','title','description','category','priority','assignedTeam','status','createdAt','aiReason','aiSuggestion','suggestedResponse','deduplication','alert','sla','actor','eventId','updatedAt','source','categoryRationale','aiClassification','priorityReason','assignmentQueue','assignmentReason','assignment','prioritySignals','deduplication','stepTrace'];
const layers = [];
let value = input;
for (let depth = 0; depth < 16; depth++) {
  if (typeof value === 'string') value = JSON.parse(value);
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Ticket payload must be a JSON object');
  layers.push(value);
  if (!Object.prototype.hasOwnProperty.call(value, 'body')) break;
  value = value.body;
  if (depth === 15) throw new Error('Webhook body nesting is too deep');
}
const ticket = {};
const trace = [];
for (const layer of layers.reverse()) {
  for (const key of allowed) if (Object.prototype.hasOwnProperty.call(layer, key)) ticket[key] = layer[key];
  if (Array.isArray(layer.workflowTrace)) for (const entry of layer.workflowTrace.slice(-32)) {
    if (typeof entry === 'string' && entry.length <= 80 && !trace.includes(entry)) trace.push(entry);
  }
}
ticket.workflowTrace = trace.slice(-32);
if (JSON.stringify(ticket).length > 65536) throw new Error('Ticket payload exceeds the workflow size limit');
ticket._workflowTime = new Date().toISOString();

for (const key of ['title', 'description']) {
  if (typeof ticket[key] !== 'string' || !ticket[key].trim()) throw new Error(key + ' is required');
  ticket[key] = ticket[key].trim();
}
if (ticket.title.length > 200 || ticket.description.length > 10000) throw new Error('Ticket text is too long');
if (ticket.ticketId !== undefined && (typeof ticket.ticketId !== 'string' || !ticket.ticketId.trim() || ticket.ticketId.length > 100)) throw new Error('Invalid ticketId');
if (ticket.ticketId) ticket.ticketId = ticket.ticketId.trim();
return [{ json: ticket }];

const ticket = $input.first().json;
const category=ticket.category??'General';
const tips={Network:'Check whether other devices can connect, reconnect to the network, and capture any error message.',Hardware:'Check power and cable connections, restart the device if safe, and note any indicator lights or error messages.',Software:'Restart the application, record the exact error, and note any recent updates or changes.',General:'Please provide the exact error message, when the issue started, and the steps already attempted.'};
return [{json:{...ticket,suggestedResponse:`We received your ticket ${ticket.ticketId}. The support team will review it. Suggested first step: ${tips[category]??tips.General}`,workflowTrace:[...(ticket.workflowTrace??[]),'WF06']}}];
